import pandas as pd,numpy as np
from sklearn.preprocessing import StandardScaler,OneHotEncoder,PolynomialFeatures
from sklearn.linear_model import RidgeCV,LinearRegression,LassoCV,ElasticNetCV,ARDRegression,BayesianRidge
from sklearn.model_selection import KFold
from sklearn.metrics import mean_squared_error
from catboost import CatBoostRegressor
tr=pd.read_csv('alloy_pair_max_train.csv');po=pd.read_csv('alloy_pair_max_pool.csv');y=tr.target.values
num=[c for c in tr.columns if c not in ['target','route','heat_treatment','Fe']]
a=pd.concat([tr.drop(columns='target'),po.drop(columns='candidate_id')]);n=StandardScaler().fit_transform(a[num]);c=OneHotEncoder(sparse_output=False,drop='first').fit_transform(a[['route','heat_treatment']]);base=np.c_[n,n**2,c];inter=np.array([n[:,j]*n[:,k] for j in range(n.shape[1]) for k in range(j)]).T;cv=list(KFold(5,shuffle=True,random_state=42).split(y))
for typ in ['ols','add_ridge','lasso','elastic','ard','bayes']+['weighted_'+str(v) for v in [.03,.07,.1,.15,.25,.5]]:
 if typ=='ols':x=base;factory=lambda:LinearRegression()
 elif typ=='add_ridge':x=base;factory=lambda:RidgeCV(alphas=np.logspace(-3,3,50))
 elif typ=='lasso':x=np.c_[base,inter];factory=lambda:LassoCV(alphas=np.logspace(-1,1,40),cv=5,max_iter=10000)
 elif typ=='elastic':x=np.c_[base,inter];factory=lambda:ElasticNetCV(alphas=np.logspace(-1,1,40),l1_ratio=[.1,.5,.9],cv=5,max_iter=10000)
 elif typ=='ard':x=np.c_[base,inter];factory=lambda:ARDRegression(max_iter=1000)
 elif typ=='bayes':x=np.c_[base,inter];factory=lambda:BayesianRidge()
 else:x=np.c_[base,inter];factory=lambda:RidgeCV(alphas=np.logspace(-2,4,60))
 p=np.zeros(len(y))
 for itr,iva in cv+[(np.arange(len(y)),np.arange(len(y),len(a)))]:
  sc=StandardScaler().fit(x[itr]);xt=sc.transform(x[itr]);xv=sc.transform(x[iva])
  if typ.startswith('weighted'):xt[:,base.shape[1]:]*=float(typ.split('_')[1]);xv[:,base.shape[1]:]*=float(typ.split('_')[1])
  m=factory().fit(xt,y[itr]);v=m.predict(xv)
  if iva[0]>=len(y):pp=v
  else:p[iva]=v
 order=np.argsort(-pp)[:8]
 print(typ,'rmse',round(mean_squared_error(y,p)**.5,3),'alpha',getattr(m,'alpha_',None),'top',list(zip(po.candidate_id.iloc[order],pp[order].round(2))),flush=True)
 if typ=='ard':
  names=num+[s+'^2' for s in num]+['cast','wrought','quench_temper','quenched','solution_aged']+[num[k]+'*'+num[j] for j in range(n.shape[1]) for k in range(j)]
  print('ARD nonzero',[(name,round(co,3)) for name,co in zip(names,m.coef_) if abs(co)>1],flush=True)
x=tr.drop(columns=['target','Fe']);p=np.zeros(len(y))
for itr,iva in cv:
 m=CatBoostRegressor(iterations=1800,depth=3,learning_rate=.025,l2_leaf_reg=4,verbose=False,thread_count=2,cat_features=['heat_treatment','route']);m.fit(x.iloc[itr],y[itr]);p[iva]=m.predict(x.iloc[iva])
m.fit(x,y);pp=m.predict(po[x.columns]);order=np.argsort(-pp)[:8]
print('catboost3','RMSE',round(mean_squared_error(y,p)**.5,3),'top',list(zip(po.candidate_id.iloc[order],pp[order].round(1))),flush=True)
